(typeof window !== "undefined" ? window : globalThis).SignalLab.guides = {"L1-1": {"steps": ["先写平移、反转、压缩对关键点的预测，点击保存初始预测。", "在参数控制依次点平移、反转、压缩、组合；每次用图上游标读峰时和峰值，点击保存本次试验。", "依次点 Δ=0.5、Δ=0.2、Δ=0.1；每组保存宽度、高度和面积。", "在推导区写关键点映射，在分析区比较预测与测量，说明窄脉冲哪些量变、哪些量不变。"], "evidence": "至少保存四种变换和三组窄脉冲；写明关键点、峰时、峰值、宽度、高度、面积及单位。"}, "L1-2": {"steps": ["保存对三个系统 2x、x²、t·x 的线性与时不变性预测。", "选线性检验，令两个输入都为常数 1，α=β=1；依次切换三个系统，保存两条比较曲线及最大差。", "切换时不变检验，输入常数 1、延迟 d=1；依次保存三个系统。", "再用正弦或余弦输入复核；把每个系统的判定和支持判定的代数关系或反例写在分析区。"], "evidence": "三个系统的两类判定、参数与比较差异；否定结论要有反例，肯定结论补代数依据。"}, "L1-3": {"steps": ["先预测三种情况下的曲线起点和长期值。", "设初值 y₀=2、输入关闭，保存零输入情况；改为 y₀=0、输入开启，保存零状态情况。", "设 y₀=2、输入开启，读 t=0、1、3、5 s 处的全响应和分量，保存本次试验。", "改为 y₀=0.5 再比较；在分析区核对每个时刻的分量之和与全响应。"], "evidence": "三种响应的参数记录、四个时刻的分量对照，补一组 y₀=0.5，解释初值与输入各自贡献。"}, "L1-4": {"steps": ["先预测两个单位矩形的卷积形状与非零范围。", "选矩形与矩形，依次用快速设置 t=−0.5、0.5、1、1.5、2.5；查看翻转平移图、乘积和积分。", "至少保存三种关键重叠情况，分析中补齐五个时刻的读数。", "切换矩形与系统冲激响应，读取 t=0.5、1、1.5、2 s 并保存比较，说明积分变量 τ 与观察时刻 t 的区别。"], "evidence": "矩形卷积五时刻读数、至少三种重叠记录；系统输出四时刻数据和 τ、t 的解释。"}, "L2-1": {"steps": ["保存对平坦区、跳变附近和过冲的预测。", "依次选择 K=1、3、7、15，每次观察合成波与单边幅度谱，保存本次试验。", "逐组记录叠加项数、最高频率和跳变附近最大值；需要时关闭各谐波显示以看清合成波。", "分析哪些位置更接近方波，以及过冲高度和影响区域是否同步消失。"], "evidence": "四组 K 的记录、项数与最高频率对照、合成图及过冲解释。"}, "L2-2": {"steps": ["设 A=1、中心 t₀=0，保存三种宽度下的频谱预测。", "依次设 T=0.5、1、2 s，每组保存 X(0) 与第一正零点。", "恢复 T=1，比较中心 0 与 1 s，在 f=0.25 Hz 处读相位并保存。", "保持宽度和中心不变，将 A 从 1 改为 2，保存对照并解释幅度变化。"], "evidence": "三宽度、一时移和一幅度比较；记录零频值、首零点、非零频谱处相位及单位。"}, "L2-3": {"steps": ["先预测截止频率 fc=100、200、500 Hz 的保留与抑制效果。", "逐个设定三种 fc，查看稳态拟合读数并保存；拟合窗口是 0.1–0.2 s。", "分别用 100 Hz 输出幅度除以 1、1000 Hz 输出幅度除以 0.3，核对两个幅度比。", "按有用分量比≥0.85 且干扰分量比≤0.25 选择最终方案，保存并用数据解释。"], "evidence": "三组候选和最终方案；两个频率的理论值、拟合幅度比、相移与逐项达标判断。"}, "L2-4": {"steps": ["原信号固定为 10 Hz 余弦，保存对三种采样率的预测。", "依次选择 fs=100、25、15 Hz，比较原信号、样本与 sinc 插值，每组保存。", "在 fs=15 Hz 下改变候选余弦频率，寻找与全部采样点吻合的低频候选并保存。", "在分析区计算 n=0、1、2、3 的样本，说明频率歧义，并区分混叠与有限样本边缘误差。"], "evidence": "三采样率与等样本候选记录、四个样本值和重建条件说明。"}, "L3-1": {"steps": ["先预测幅度、衰减率和时移分别进入变换式的哪个位置。", "选指数型，A=1，依次设 a=0.5、1、2，填受限答案模板并逐组保存。", "分别选阶跃和矩形，比较延迟或持续时间，填模板并保存。", "独立题：选延迟矩形，设 A=3、开始 t₁=1 s、持续 T=2 s；先在推导区写两个阶跃，再填模板、看反馈并保存。"], "evidence": "四种模型及三种衰减率的模板记录；独立题写出开始、结束、持续时间和完整变换。"}, "L3-2": {"steps": ["先预测 y(1) 与达到最终值 90% 的时间并保存。", "从零初值方程 y′+y=u(t) 写出 H(s)、X(s)、Y(s)，再做部分分式。", "在右侧填写 aH、bX、C、D，观察学生解析曲线与独立 RK4 曲线。", "将测量时刻设为 0、1 和接近 t90 的时刻，逐组保存；在推导区保留逆变换过程，在分析区解释核验结果。"], "evidence": "H、X、Y、部分分式、模板与推导；y(0)、y(1)、t90 的读数和曲线比较。"}, "L3-3": {"steps": ["先预测 y₀=0、0.5、2 的起点、方向和长期值。", "分别选三种初值，在推导中保留 sY−y₀，再求 Y 与时域响应。", "每次更新模板的初始项、C、D，不能只换曲线不改答案；读取起点和 t=1 s，逐组保存。", "比较零输入、零状态和全响应，解释为什么最终值相同而过渡过程不同。"], "evidence": "三初值的推导、对应模板、分量和读数；写明起点、变化方向与长期值。"}, "L3-4": {"steps": ["保存对 T=0.5、1、2、3 s 峰值和峰时的预测。", "依次设四种 T，每组保存峰值、峰时和达标状态。", "由两个阶跃之差推导响应及峰值条件，在临界区至少再试两组更细的 T，保存失败与成功记录。", "选最短达标方案并保存，在分析区说明参数步长、理论下界，以及为何相邻更短方案不达标。"], "evidence": "四候选、至少两次细调及最终方案；Y(s)、时移响应、峰值不等式与最短性依据。"}};
